//! V&V: differential comparison of this crate against CoolProp itself (gh:#1349).
//!
//! ## Methodology
//!
//! The reference is CoolProp's own output, produced by `coolprop_driver.cpp` linked against
//! CoolProp commit `0e67fe74b30a2fe9526af9bc64ea026a96f56ebf` (the commit this crate ports)
//! built from source with g++ 13.3 / glibc 2.39, no `-ffast-math`, no FMA. Inputs are grids
//! generated by rule (see `verification_and_validation/coolprop_differential/PREDICTIONS.md`,
//! committed before the first run); the driver prints the `(T, rho)` it fed CoolProp and
//! CoolProp's own `delta`, `tau`, and this test consumes exactly those bits.
//!
//! Compared per fluid and per term: `alphar` + 5 derivatives, `alpha0` + 5 derivatives,
//! `p, u, h, s, cv, cp, w` at `(T, rho)`, `mu`, `lambda`, the saturation ancillary fits, the
//! full saturation solve, and the `(p,T)` flash (root identity and value), with `(p,h)` and
//! `(p,s)` round trips. The metric is `|a-b| / max(|a|,|b|)`; the counts of bit-identical
//! values are reported with it.
//!
//! Results: `verification_and_validation/coolprop_differential/RESULTS.md`.
//!
//! Set `COOLPROP_FULL_REF=<path to uncompressed full reference CSV>` to analyse the full
//! reference (not committed: it is ~7 MB) and print the full report.

use miniz_oxide::inflate::decompress_to_vec;
use outram_park_fork_coolprop::ancillaries::{
    saturated_liquid_density_ancillary, saturated_vapour_density_ancillary,
    saturation_pressure_ancillary,
};
use outram_park_fork_coolprop::{
    conductivity, saturation_at_temperature, state_ph, state_ps, state_pt, state_trho, viscosity,
    Fluid,
};
use std::collections::BTreeMap;
use std::panic::{catch_unwind, AssertUnwindSafe};

pub fn gunzip(bytes: &[u8]) -> String {
    assert!(bytes.len() > 18 && bytes[0] == 0x1f && bytes[1] == 0x8b && bytes[3] == 0);
    let raw = decompress_to_vec(&bytes[10..bytes.len() - 8]).expect("inflate");
    String::from_utf8(raw).expect("utf8")
}

fn num(s: &str) -> f64 {
    if s == "nan" {
        f64::NAN
    } else {
        s.parse::<f64>().expect("float")
    }
}

/// Relative difference, `0` when equal (including both NaN is NOT equal: see `Stat::add`).
pub fn rel(a: f64, b: f64) -> f64 {
    if a == b {
        0.0
    } else {
        (a - b).abs() / a.abs().max(b.abs())
    }
}

/// Accumulated agreement for one (fluid, quantity).
#[derive(Debug, Clone, Default)]
pub struct Stat {
    pub n: usize,
    pub bit: usize,
    pub worst: f64,
    pub worst_at: String,
    /// CoolProp returned a number, this crate did not (None / NaN / panic).
    pub rust_missing: usize,
    /// This crate returned a number, CoolProp did not.
    pub cp_missing: usize,
}

impl Stat {
    pub fn add(&mut self, cp: f64, rs: Option<f64>, at: &str) {
        match (cp.is_finite(), rs.filter(|x| x.is_finite())) {
            (true, Some(r)) => {
                self.n += 1;
                if cp.to_bits() == r.to_bits() || cp == r {
                    self.bit += 1;
                }
                let d = rel(cp, r);
                if d > self.worst {
                    self.worst = d;
                    self.worst_at = at.to_string();
                }
            }
            (true, None) => self.rust_missing += 1,
            (false, Some(_)) => self.cp_missing += 1,
            (false, None) => {}
        }
    }
}

/// Per-(fluid, term) statistics, keyed by fluid name and term label.
pub type Table = BTreeMap<(String, &'static str), Stat>;

fn fluid_by_name(name: &str) -> Option<Fluid> {
    Fluid::ALL.iter().copied().find(|f| f.name() == name)
}

fn guarded<T>(f: impl FnOnce() -> T) -> Option<T> {
    catch_unwind(AssertUnwindSafe(f)).ok()
}

const E_TERMS: [&str; 12] = [
    "ar", "ar_d", "ar_t", "ar_dd", "ar_dt", "ar_tt", "a0", "a0_d", "a0_t", "a0_dd", "a0_dt",
    "a0_tt",
];
const P_TERMS: [&str; 9] = ["p", "u", "h", "s", "cv", "cp", "w", "mu", "lambda"];

/// Analyse the rows of a reference CSV. Returns the per-(fluid, term) table.
pub fn analyse(text: &str) -> Table {
    analyse_with_log(text, &mut Vec::new())
}

fn crit_key(term: &str) -> &'static str {
    match term {
        "cp" => "cp@crit",
        "w" => "w@crit",
        _ => "lambda@crit",
    }
}

/// As [`analyse`], also logging every value that differs by more than `1e-9` or is missing on
/// one side, as `fluid,term,at,coolprop,rust,rel`.
pub fn analyse_with_log(text: &str, log: &mut Vec<String>) -> Table {
    let mut t: Table = BTreeMap::new();
    let mut push = |t: &mut Table, f: &str, term: &'static str, cp: f64, rs: Option<f64>, at: &str| {
        // The exact critical point (tau = delta = 1, row 156 of the E grid) is a singular point
        // of cp and of the compressibility: reported under its own key, never mixed in.
        let term = if at == "156" && (term == "cp" || term == "w" || term == "lambda") {
            crit_key(term)
        } else {
            term
        };
        t.entry((f.to_string(), term)).or_default().add(cp, rs, at);
        let r = rs.filter(|x| x.is_finite());
        let flag = match r {
            Some(r) if cp.is_finite() => rel(cp, r) > 1e-9,
            Some(_) => true,
            None => cp.is_finite(),
        };
        if flag {
            let d = match r {
                Some(r) if cp.is_finite() => rel(cp, r),
                _ => f64::NAN,
            };
            log.push(format!(
                "{f},{term},{at},{cp:e},{},{d:.3e}",
                r.map_or("none".to_string(), |x| format!("{x:e}"))
            ));
        }
    };
    for line in text.lines() {
        let c: Vec<&str> = line.split(',').collect();
        let tag = c[0];
        let Some(fluid) = c.get(1).and_then(|n| fluid_by_name(n)) else {
            continue;
        };
        let name = c[1];
        match tag {
            "E" => {
                let idx = c[2];
                let tk = num(c[3]);
                let rho = num(c[4]);
                let delta = num(c[5]);
                let tau = num(c[6]);
                let v: Vec<f64> = c[7..].iter().map(|s| num(s)).collect();
                let eos = fluid.eos();
                // input consistency: does this crate form delta, tau the same bits?
                let d_rs = rho / eos.molar_mass / eos.rho_reducing;
                let t_rs = eos.t_reducing / tk;
                push(&mut t, name, "in_delta", delta, Some(d_rs), idx);
                push(&mut t, name, "in_tau", tau, Some(t_rs), idx);
                let res = eos.residual_derivs(delta, tau);
                let ide = eos.ideal_derivs(delta, tau);
                let rs = [
                    res.a, res.ad, res.at, res.add, res.adt, res.att, ide.a, ide.ad, ide.at,
                    ide.add, ide.adt, ide.att,
                ];
                for k in 0..12 {
                    push(&mut t, name, E_TERMS[k], v[k], Some(rs[k]), idx);
                }
                let st = guarded(|| state_trho(fluid, tk, rho));
                let pv = [
                    st.map(|s| s.pressure),
                    st.map(|s| s.internal_energy),
                    st.map(|s| s.enthalpy),
                    st.map(|s| s.entropy),
                    st.map(|s| s.cv),
                    st.map(|s| s.cp),
                    st.map(|s| s.speed_of_sound),
                    viscosity(fluid, tk, rho),
                    conductivity(fluid, tk, rho),
                ];
                for k in 0..9 {
                    push(&mut t, name, P_TERMS[k], v[12 + k], pv[k], idx);
                }
            }
            "SATA" => {
                let tk = num(c[2]);
                let at = c[2];
                push(&mut t, name, "anc_p", num(c[3]), saturation_pressure_ancillary(fluid, tk), at);
                push(&mut t, name, "anc_rhoL", num(c[4]), saturated_liquid_density_ancillary(fluid, tk), at);
                push(&mut t, name, "anc_rhoV", num(c[5]), saturated_vapour_density_ancillary(fluid, tk), at);
            }
            "SAT" | "SATS" => {
                let tk = num(c[2]);
                let sat = guarded(|| saturation_at_temperature(fluid, tk)).flatten();
                let (a, b, cc) = if tag == "SAT" {
                    ("sat_p", "sat_rhoL", "sat_rhoV")
                } else {
                    ("sats_p", "sats_rhoL", "sats_rhoV")
                };
                push(&mut t, name, a, num(c[3]), sat.map(|s| s.pressure), c[2]);
                push(&mut t, name, b, num(c[4]), sat.map(|s| s.rho_liquid), c[2]);
                push(&mut t, name, cc, num(c[5]), sat.map(|s| s.rho_vapour), c[2]);
            }
            "PT" => {
                let tk = num(c[2]);
                let p = num(c[3]);
                let at = format!("T={},p={}", c[2], c[3]);
                let (rho, h, s) = (num(c[4]), num(c[5]), num(c[6]));
                let st = guarded(|| state_pt(fluid, tk, p)).and_then(|r| r.ok());
                push(&mut t, name, "pt_rho", rho, st.map(|x| x.density), &at);
                push(&mut t, name, "pt_h", h, st.map(|x| x.enthalpy), &at);
                push(&mut t, name, "pt_s", s, st.map(|x| x.entropy), &at);
                // round trips from CoolProp's own h and s
                let tph = guarded(|| state_ph(fluid, p, h)).and_then(|r| r.ok());
                let tps = guarded(|| state_ps(fluid, p, s)).and_then(|r| r.ok());
                push(&mut t, name, "ph_T", tk, tph.map(|x| x.temperature), &at);
                push(&mut t, name, "ps_T", tk, tps.map(|x| x.temperature), &at);
            }
            _ => {}
        }
    }
    t
}

/// Per-term aggregate over all fluids.
pub fn totals(t: &Table) -> BTreeMap<&'static str, Stat> {
    let mut out: BTreeMap<&'static str, Stat> = BTreeMap::new();
    for ((f, term), s) in t {
        let e = out.entry(term).or_default();
        e.n += s.n;
        e.bit += s.bit;
        e.rust_missing += s.rust_missing;
        e.cp_missing += s.cp_missing;
        if s.worst > e.worst {
            e.worst = s.worst;
            e.worst_at = f.clone();
        }
    }
    out
}

pub fn report(t: &Table) -> String {
    let mut o = String::new();
    o.push_str("term,n,bit_identical,worst_rel,worst_fluid,rust_missing,cp_missing\n");
    for (term, s) in totals(t) {
        o.push_str(&format!(
            "{term},{},{},{:.3e},{},{},{}\n",
            s.n, s.bit, s.worst, s.worst_at, s.rust_missing, s.cp_missing
        ));
    }
    o.push_str("\nfluid,term,n,bit_identical,worst_rel,worst_at,rust_missing,cp_missing\n");
    for ((f, term), s) in t {
        o.push_str(&format!(
            "{f},{term},{},{},{:.3e},{},{},{}\n",
            s.n, s.bit, s.worst, s.worst_at, s.rust_missing, s.cp_missing
        ));
    }
    o
}

/// Print this crate's own `alphar` and derivatives for `fluid:idx` pairs listed in
/// `COOLPROP_DUMP` (comma separated), using the `(delta, tau)` of the reference row. Used to
/// localise a difference against a high-precision evaluation (see RESULTS.md).
fn dump_rust_terms(text: &str, spec: &str) -> String {
    let mut o = String::new();
    for item in spec.split(';') {
        let Some((name, idx)) = item.split_once(':') else {
            continue;
        };
        let Some(fluid) = fluid_by_name(name) else {
            continue;
        };
        for line in text.lines() {
            let c: Vec<&str> = line.split(',').collect();
            if c[0] == "E" && c[1] == name && c[2] == idx {
                let (delta, tau) = (num(c[5]), num(c[6]));
                let r = fluid.eos().residual_derivs(delta, tau);
                o.push_str(&format!(
                    "RUST,{name},{idx},{:.17e},{:.17e},{:.17e},{:.17e},{:.17e},{:.17e}\n",
                    r.a, r.ad, r.at, r.add, r.adt, r.att
                ));
                o.push_str(&format!("CP,{name},{idx},{}\n", c[7..13].join(",")));
                o.push_str(&format!("IN,{name},{idx},{},{}\n", c[5], c[6]));
            }
        }
    }
    o
}

#[test]
fn full_reference_report() {
    let Ok(path) = std::env::var("COOLPROP_FULL_REF") else {
        return;
    };
    let text = std::fs::read_to_string(&path).expect("read full reference");
    if let Ok(spec) = std::env::var("COOLPROP_DUMP") {
        println!("{}", dump_rust_terms(&text, &spec));
        if let Ok(dst) = std::env::var("COOLPROP_REPORT_OUT") {
            std::fs::write(dst, dump_rust_terms(&text, &spec)).expect("write dump");
        }
        return;
    }
    let mut log = Vec::new();
    let t = analyse_with_log(&text, &mut log);
    if let Ok(dst) = std::env::var("COOLPROP_LOG_OUT") {
        std::fs::write(dst, log.join("\n")).expect("write log");
    }
    let out = report(&t);
    if let Ok(dst) = std::env::var("COOLPROP_REPORT_OUT") {
        std::fs::write(dst, &out).expect("write report");
    } else {
        println!("{out}");
    }
}

/// Round `x` UP to two significant figures: the pinned bound of a worst difference. Bounds are
/// never widened to make a run pass; a deliberate re-pin records old and new in RESULTS.md.
pub fn bound2(x: f64) -> f64 {
    if x <= 0.0 {
        return 0.0;
    }
    let e = x.log10().floor() as i32 - 1;
    let scale = 10f64.powi(e);
    (x / scale).ceil() * scale
}

/// The pin table: `fluid,term,n,bit_identical,worst_bound,rust_missing,cp_missing`.
pub fn pins_text(t: &Table) -> String {
    let mut o = String::from("fluid,term,n,bit_identical,worst_bound,rust_missing,cp_missing\n");
    for ((f, term), s) in t {
        o.push_str(&format!(
            "{f},{term},{},{},{:.1e},{},{}\n",
            s.n,
            s.bit,
            bound2(s.worst),
            s.rust_missing,
            s.cp_missing
        ));
    }
    o
}

fn read_gz(path: &str) -> String {
    let bytes = std::fs::read(format!(
        "{}/verification_and_validation/coolprop_differential/{path}",
        env!("CARGO_MANIFEST_DIR")
    ))
    .expect("committed reference present");
    gunzip(&bytes)
}

/// The committed subset of CoolProp's output, analysed against this crate, against the
/// committed pin table: counts of compared / missing values exactly, the bit-identical count
/// not below the pin, and the worst relative difference not above the pinned bound.
#[test]
fn subset_reference_matches_the_committed_pins() {
    let t = analyse(&read_gz("coolprop_subset.csv.gz"));
    if let Ok(dst) = std::env::var("COOLPROP_WRITE_PINS") {
        std::fs::write(dst, pins_text(&t)).expect("write pins");
        return;
    }
    let pins = read_gz("pins.csv.gz");
    let mut seen = 0usize;
    let mut bad = Vec::new();
    for line in pins.lines().skip(1) {
        let c: Vec<&str> = line.split(',').collect();
        let (f, term) = (c[0], c[1]);
        let n: usize = c[2].parse().unwrap();
        let bit: usize = c[3].parse().unwrap();
        let bound: f64 = c[4].parse().unwrap();
        let (rm, cm): (usize, usize) = (c[5].parse().unwrap(), c[6].parse().unwrap());
        let Some((_, s)) = t.iter().find(|((ff, tt), _)| ff == f && *tt == term) else {
            bad.push(format!("{f} {term}: pinned but not produced"));
            continue;
        };
        seen += 1;
        if s.n != n || s.rust_missing != rm || s.cp_missing != cm {
            bad.push(format!(
                "{f} {term}: counts n {}->{} rust_missing {}->{} cp_missing {}->{}",
                n, s.n, rm, s.rust_missing, cm, s.cp_missing
            ));
        }
        if s.bit < bit {
            bad.push(format!("{f} {term}: bit-identical fell {bit} -> {}", s.bit));
        }
        if s.worst > bound {
            bad.push(format!("{f} {term}: worst {:.3e} exceeds pinned bound {bound:.1e}", s.worst));
        }
    }
    assert_eq!(seen, t.len(), "every (fluid, term) produced must be pinned");
    assert!(
        bad.is_empty(),
        "{} pin violations, first 20:\n{}",
        bad.len(),
        bad.iter().take(20).cloned().collect::<Vec<_>>().join("\n")
    );
}

/// Headline guarantees asserted directly, so that a re-pin cannot hide them.
#[test]
fn subset_headline_guarantees() {
    let t = analyse(&read_gz("coolprop_subset.csv.gz"));
    let tot = totals(&t);
    // Inputs are formed identically, and alpha0's delta-derivative and mixed derivative are
    // bit-identical on every compared value.
    for term in ["a0_d", "a0_dt", "in_delta", "in_tau"] {
        let s = &tot[term];
        assert_eq!(s.bit, s.n, "{term} must be bit-identical on every compared value");
    }
    // The ancillary fits agree with CoolProp's to rounding.
    for term in ["anc_p", "anc_rhoL", "anc_rhoV"] {
        assert!(tot[term].worst < 1e-14, "{term} worst {:.3e}", tot[term].worst);
    }
    // The flash is exercised (guards against an empty reference).
    assert!(tot["pt_rho"].n > 1000);
}
